CREATE TABLE IF NOT EXISTS departments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','MANAGER','USER')), department_id BIGINT REFERENCES departments(id), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS clients (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, contact VARCHAR(150) NOT NULL, description VARCHAR(4000) NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(4000) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('PLANNED','ACTIVE','DONE')), owner_id BIGINT NOT NULL REFERENCES users(id), client_id BIGINT REFERENCES clients(id), due_date DATE NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(4000) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('TODO','DOING','DONE')), owner_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT NOT NULL REFERENCES projects(id), due_date DATE NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS approvals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(4000) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','PENDING','APPROVED','REJECTED')), owner_id BIGINT NOT NULL REFERENCES users(id), approver_id BIGINT NOT NULL REFERENCES users(id), decision_note VARCHAR(1000) NOT NULL DEFAULT '', version INT NOT NULL DEFAULT 0, CHECK(owner_id <> approver_id));
CREATE TABLE IF NOT EXISTS notices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(4000) NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(40) NOT NULL, action VARCHAR(40) NOT NULL, target VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
